#include <cstddef>
#include <cstdint>
static void put_i32(std::uint8_t*out,std::size_t i,std::int64_t x){auto v=static_cast<std::uint32_t>(static_cast<std::int32_t>(x));out[4*i]=v;out[4*i+1]=v>>8;out[4*i+2]=v>>16;out[4*i+3]=v>>24;}
extern "C" std::int64_t insert_delete_in_array(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap) noexcept {if(!v||n<4||n>260)return -1;auto op=v[0],len=v[1],pos=v[2],element=v[3];if((op!=0&&op!=1)||len<0||len>256||n!=static_cast<std::size_t>(len)+4||pos<0||(op==0?pos>len:pos>=len)||(op==1&&element!=0))return -1;for(std::size_t i=0;i<static_cast<std::size_t>(len);i++)if(v[i+4]<INT32_MIN||v[i+4]>INT32_MAX)return -1;if(op==0&&(element<INT32_MIN||element>INT32_MAX))return -1;auto outn=static_cast<std::size_t>(len)+(op==0);if(outn*4>cap||(outn>0&&!out))return -2;for(std::size_t i=0;i<outn;i++){auto x=op==0?(i<static_cast<std::size_t>(pos)?v[i+4]:(i==static_cast<std::size_t>(pos)?element:v[i+3])):(i<static_cast<std::size_t>(pos)?v[i+4]:v[i+5]);put_i32(out,i,x);}return static_cast<std::int64_t>(outn*4);}
